// Serialize commands so rapid key presses cannot overlap.
let queue = Promise.resolve();

// Ignore the detach event generated by our own return operation.
const returning = new Set();

chrome.tabs.onDetached.addListener(
  (tabId, { oldWindowId, oldPosition }) => {
    if (returning.delete(tabId)) return;

    queue = queue.then(async () => {
      const key = `origin:${tabId}`;
      const saved = (await chrome.storage.session.get(key))[key];

      // Preserve the original home even after further window moves.
      if (!saved) {
        await chrome.storage.session.set({
          [key]: {
            windowId: oldWindowId,
            index: oldPosition
          }
        });
      }
    }).catch(console.error);
  }
);

// If you manually drag a tab home, finish that detach/return cycle.
chrome.tabs.onAttached.addListener(
  (tabId, { newWindowId }) => {
    queue = queue.then(async () => {
      const key = `origin:${tabId}`;
      const saved = (await chrome.storage.session.get(key))[key];

      if (saved?.windowId === newWindowId) {
        await chrome.storage.session.remove(key);
      }
    }).catch(console.error);
  }
);
chrome.commands.onCommand.addListener(command => {
  queue = queue.then(() => run(command)).catch(console.error);
});

async function run(command) {
  const [tab] = await chrome.tabs.query({
    active: true,
    currentWindow: true
  });
  if (!tab) return;

  const key = `origin:${tab.id}`;
  const saved = (await chrome.storage.session.get(key))[key];

  if (command === "detach") {
    // Keep an existing original-window record.
    if (saved) return;

    const siblings = await chrome.tabs.query({
      windowId: tab.windowId
    });

    // Keep the source window alive if this is its last tab.
    if (siblings.length === 1) {
      await chrome.tabs.create({
        windowId: tab.windowId,
        active: false
      });
    }

    await chrome.storage.session.set({
      [key]: {
        windowId: tab.windowId,
        index: tab.index,
        pinned: tab.pinned
      }
    });

    try {
      await chrome.windows.create({
        tabId: tab.id,
        focused: true
      });
    } catch (error) {
      await chrome.storage.session.remove(key);
      throw error;
    }
  }

  if (command === "reattach" && saved) {
    // If the original window was closed, leave the tab alone.
    try {
      await chrome.windows.get(saved.windowId);
    } catch {
      await chrome.storage.session.remove(key);
      return;
    }
    
    returning.add(tab.id);

    try {
      await chrome.tabs.move(tab.id, {
        windowId: saved.windowId,
        index: saved.index
      });
    } catch (error) {
      returning.delete(tab.id);
      throw error;
    }
    await chrome.tabs.update(tab.id, {
      active: true,
      pinned: saved.pinned
    });
    await chrome.windows.update(saved.windowId, {
      focused: true
    });
    await chrome.storage.session.remove(key);
  }
}

chrome.tabs.onRemoved.addListener(tabId => {
  chrome.storage.session.remove(`origin:${tabId}`);
});